recipes.code:
{
  "inputs": [
    {
      "id": "wallet-private-key",
      "type": "promptString",
      "description": "Funded Base wallet private key for x402 payment signing (optional; without it, paid tools return the 402 requirements).",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@true402.dev/mcp-server@1.0.4"
      ],
      "env": {
        "WALLET_PRIVATE_KEY": "${input:wallet-private-key}",
        "SERVER_URL": "<server-url>",
        "MAX_PAYMENT_USDC": "<max-payment-usdc>"
      }
    }
  }
}
